import{_ as t,o,c as d,ao as i}from"./chunks/framework.ucUddl5u.js";const g=JSON.parse('{"title":"API — Kernel","description":"","frontmatter":{},"headers":[],"relativePath":"ref/api-kernel.md","filePath":"ref/api-kernel.md","lastUpdated":null}'),l={name:"ref/api-kernel.md"};function r(a,e,n,s,c,h){return o(),d("div",null,[...e[0]||(e[0]=[i('<h1 id="API-—-Kernel" tabindex="-1">API — Kernel <a class="header-anchor" href="#API-—-Kernel" aria-label="Permalink to &quot;API — Kernel {#API-—-Kernel}&quot;">​</a></h1><p>The Julia <strong>kernel</strong> (<code>ShipToolsKernel</code>) is the plugin host process. It owns the dispatch tables, computes mode trees, indexes the project, hashes ASTs, and produces Julia-aware previews — exposing all of it to the backend daemon over an NDJSON line protocol.</p><div class="tip custom-block"><p class="custom-block-title">Reference under construction</p><p>Per-symbol API docs for <code>ShipToolsKernel</code> are not yet wired into this site (the kernel module is not currently a dependency of the docs build). For now:</p><ul><li><p>The wire protocol it speaks: <a href="./../design/protocol">Line Protocol</a>.</p></li><li><p>The ABI it dispatches on: <a href="./api-core">API — ConceptExplorerCore</a> and <a href="./../extend/abi">The Dispatch ABI</a>.</p></li></ul><p>Source: <code>julia/kernel/src/ShipToolsKernel.jl</code>.</p></div><h2 id="builtin-preview-plugins" tabindex="-1">Built-in preview plugins <a class="header-anchor" href="#builtin-preview-plugins" aria-label="Permalink to &quot;Built-in preview plugins {#builtin-preview-plugins}&quot;">​</a></h2><p>The standard file types ship under <code>julia/plugins/</code> and the kernel loads them at startup. The MIME type tells the frontend which renderer to use; what each one shows is in <a href="./../guide/previews">Previews</a>.</p><table tabindex="0"><thead><tr><th style="text-align:right;">Extension</th><th style="text-align:right;">Plugin</th><th style="text-align:right;">MIME</th></tr></thead><tbody><tr><td style="text-align:right;"><code>.jl</code></td><td style="text-align:right;"><code>ShipToolsJuliaSource</code></td><td style="text-align:right;"><code>application/vnd.sot.tokens+json</code></td></tr><tr><td style="text-align:right;"><code>.md</code>, <code>.markdown</code></td><td style="text-align:right;"><code>ShipToolsMarkdown</code></td><td style="text-align:right;"><code>text/markdown</code></td></tr><tr><td style="text-align:right;"><code>.toml</code></td><td style="text-align:right;"><code>ShipToolsTomlDoc</code></td><td style="text-align:right;"><code>text/x-toml</code></td></tr><tr><td style="text-align:right;"><code>.json</code></td><td style="text-align:right;"><code>ShipToolsJsonDoc</code></td><td style="text-align:right;"><code>application/json</code></td></tr><tr><td style="text-align:right;"><code>.txt</code></td><td style="text-align:right;"><code>ShipToolsPlainText</code></td><td style="text-align:right;"><code>text/plain</code></td></tr><tr><td style="text-align:right;"><code>.pdf</code></td><td style="text-align:right;"><code>ShipToolsPDFFile</code></td><td style="text-align:right;"><code>image/png</code> (+ <code>page</code>, <code>page_count</code> extras)</td></tr><tr><td style="text-align:right;"><code>.mp4</code>, <code>.webm</code>, <code>.mov</code>, <code>.mkv</code>, <code>.m4v</code></td><td style="text-align:right;"><code>ShipToolsVideoFile</code></td><td style="text-align:right;"><code>image/png</code></td></tr></tbody></table>',6)])])}const u=t(l,[["render",r]]);export{g as __pageData,u as default};
